// Normalizador del subworkflow registrar_alumno
// Devuelve SIEMPRE [{ json: ... }] y completa defaults

const data = $input.first()?.json ?? {};

const norm = (v) => (v === undefined || v === null ? "" : String(v).trim());

return [
  {
    json: {
      whatsapp: norm(data.whatsapp),
      nombre: norm(data.nombre) || "No especificado",
      nivel: norm(data.nivel) || "Sin definir",
      notas: norm(data.notas), // backup libre
      objetivo: norm(data.objetivo),
      disponibilidad: norm(data.disponibilidad),
      lead_tipo: norm(data.lead_tipo),
      origen: norm(data.origen),
      intencion: norm(data.intencion),
      completitud: norm(data.completitud),
      kids_edad: norm(data.kids_edad),
      kids_colegio: norm(data.kids_colegio),
      kids_turno: norm(data.kids_turno),
      kids_grado: norm(data.kids_grado),
      referencia: norm(data.referencia),
      tags: norm(data.tags),
      resumen: norm(data.resumen)
    }
  }
];
